package com.jgeted.sagadyssey.social.industry;
import com.jgeted.sagadyssey.social.industry.common.*;
import net.minecraft.nbt.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class NativeActionContractTest {
    private CompoundTag source(){var t=new CompoundTag();for(String k:List.of("Id","Target","Owner","Actor","Need"))t.putUUID(k,UUID.randomUUID());t.putString("Kind","SHEAR");t.put("Output",new CompoundTag());return t;}
    private CompoundTag action(CompoundTag s){var a=new CompoundTag();for(String k:List.of("Id","Person","Body","Plan"))a.putUUID(k,UUID.randomUUID());a.putUUID("Source",s.getUUID("Id"));a.putUUID("Need",s.getUUID("Need"));a.putString("State","READY");return a;}
    @Test void observationCopiesNeverChangeAuthority(){var d=new EntityResourceActionData();var s=source();d.putSource(s);s.putString("Kind","FISH_COD");assertEquals("SHEAR",d.sources().getFirst().getString("Kind"));d.setDirty(false);d.sources().getFirst().putString("Kind","invalid");assertFalse(d.isDirty());assertEquals("SHEAR",d.source(s.getUUID("Id")).getString("Kind"));}
    @Test void sourceBindingConflictsReject(){var d=new EntityResourceActionData();var s=source();d.putSource(s);s.putUUID("Actor",UUID.randomUUID());assertThrows(IllegalStateException.class,()->d.putSource(s));}
    @Test void sameBodyCanRebindPlanButNotPerson(){var d=new EntityResourceActionData();var s=source();d.putSource(s);var a=action(s);d.putAction(a);a.putUUID("Plan",UUID.randomUUID());d.putAction(a);a.putUUID("Person",UUID.randomUUID());assertThrows(IllegalStateException.class,()->d.putAction(a));}
    @Test void terminalFactsCannotBecomeNewActions(){var d=new EntityResourceActionData();var s=source();d.putSource(s);var a=action(s);a.putString("State","DONE");d.putAction(a);a.putString("State","READY");assertThrows(IllegalStateException.class,()->d.putAction(a));}
    @Test void uncertainNativeResultSurvivesNbtWithoutClaimingSuccess(){var d=new EntityResourceActionData();var s=source();d.putSource(s);var a=action(s);a.putString("State","ACTING");d.putAction(a);var r=EntityResourceActionData.load(d.save(new CompoundTag(),null),null);assertFalse(r.isDirty());assertEquals("ACTING",r.action(a.getUUID("Id")).getString("State"));assertEquals(a,r.action(a.getUUID("Id")));}
    @Test void duplicatePersistedOperationsReject(){var d=new EntityResourceActionData();var s=source();d.putSource(s);var a=action(s);d.putAction(a);var root=d.save(new CompoundTag(),null);root.getList("Actions",Tag.TAG_COMPOUND).add(a.copy());assertThrows(IllegalArgumentException.class,()->EntityResourceActionData.load(root,null));}
    @Test void unsupportedSchemaRejects(){var t=new CompoundTag();t.putInt("Schema",2);assertThrows(IllegalArgumentException.class,()->EntityResourceActionData.load(t,null));}
    @Test void cacheIdentityIgnoresOnlyRevisions(){var a=new CompoundTag();a.putString("Actor","a");a.putInt("Quantity",3);a.putString("Destination","x");a.putString("Intent","DELIVERY");a.putString("ExpectedRevisions","old");var b=a.copy();b.putString("ExpectedRevisions","new");assertTrue(IndustryTransfers.sameEffect(a,b));for(String k:List.of("Actor","Destination","Intent")){var c=b.copy();c.putString(k,"changed");assertFalse(IndustryTransfers.sameEffect(a,c));}b.putInt("Quantity",4);assertFalse(IndustryTransfers.sameEffect(a,b));assertFalse(IndustryTransfers.sameEffect(null,a));}
    @Test void generatorSelectsOneExactNamespacePerFrozenPhase(){var a=System.getProperty("sagadyssey.industry.native");var b=System.getProperty("sagadyssey.industry.ab.phase");try{System.setProperty("sagadyssey.industry.native","true");for(String p:List.of("guards","wool-start","wool-resume","fish","smelt-start","smelt-resume")){System.setProperty("sagadyssey.industry.ab.phase",p);var tests=EntityFurnaceGameTests.tests();assertEquals(1,tests.size());assertTrue(tests.iterator().next().structureName().startsWith("sagadyssey_industries_ab:"));}System.setProperty("sagadyssey.industry.native","false");assertTrue(EntityFurnaceGameTests.tests().isEmpty());}finally{if(a==null)System.clearProperty("sagadyssey.industry.native");else System.setProperty("sagadyssey.industry.native",a);if(b==null)System.clearProperty("sagadyssey.industry.ab.phase");else System.setProperty("sagadyssey.industry.ab.phase",b);}}
}
